67	/**
68	 * Rebuild the local Chronicle session store by re-reading JSONL debug logs from disk.
69	 */
70	export async function reindexSessions(
71		store: ISessionStore,
72		debugLogService: IChatDebugFileLoggerService,
73		reportProgress: (message: string) => void,
74		token: CancellationToken,
75		force: boolean = false,
76	): Promise<ReindexResult> {
77		const sessionIds = await debugLogService.listSessionIds();
78	
79		let processed = 0;
80		let skipped = 0;
81	
82		for (let i = 0; i < sessionIds.length; i++) {
83			if (token.isCancellationRequested) {
84				return { processed, skipped, cancelled: true };
85			}
86	
87			const sessionId = sessionIds[i];
88	
89			// Fast-path: skip sessions already in the store unless force mode
90			if (!force && store.getSession(sessionId)) {
91				skipped++;
92				continue;
93			}
94	
95			reportProgress(l10n.t('Reindexing session {0} of {1}...', i + 1, sessionIds.length));
96	
97			try {
98				await reindexOneSession(store, debugLogService, sessionId);
99				processed++;
100			} catch {
101				// Non-fatal — skip corrupt/unreadable sessions
102				skipped++;
103			}
104	
105			// Yield to event loop between sessions to avoid blocking the extension host
106			await new Promise<void>(resolve => setTimeout(resolve, 0));
107		}
108	
109		return { processed, skipped, cancelled: false };
110	}
