112	/**
113	 * Reindex a single session from its JSONL debug log.
114	 * Streams events, builds a bounded per-session buffer, and flushes atomically.
115	 */
116	async function reindexOneSession(
117		store: ISessionStore,
118		debugLogService: IChatDebugFileLoggerService,
119		sessionId: string,
120	): Promise<void> {
121		const buffer: PerSessionWriteBuffer = {
122			session: undefined,
123			turns: [],
124			files: [],
125			refs: [],
126		};
127	
128		// State for turn pairing — tracks the pending user message to pair with next assistant response.
129		let pendingUserMessage: string | undefined;
130		let pendingUserTimestamp: string | undefined;
131		let turnIndex = 0;
132	
133		await debugLogService.streamEntries(sessionId, (entry: IDebugLogEntry) => {
134			processEntry(entry, sessionId, buffer, {
135				get pendingUserMessage() { return pendingUserMessage; },
136				set pendingUserMessage(v) { pendingUserMessage = v; },
137				get pendingUserTimestamp() { return pendingUserTimestamp; },
138				set pendingUserTimestamp(v) { pendingUserTimestamp = v; },
139				get turnIndex() { return turnIndex; },
140				set turnIndex(v) { turnIndex = v; },
141			});
142		});
143	
144		// If there's a trailing user message without a paired assistant response, flush it
145		if (pendingUserMessage) {
146			buffer.turns.push({
147				session_id: sessionId,
148				turn_index: turnIndex,
149				user_message: truncateForStore(pendingUserMessage, MAX_USER_MESSAGE_LENGTH),
150				timestamp: pendingUserTimestamp,
151			});
152		}
153	
154		// Ensure we always have a session row (even if no session_start event was found)
155		if (!buffer.session) {
156			buffer.session = { id: sessionId, host_type: 'vscode' };
157		}
158	
159		// Flush all buffered data in a single transaction
160		store.runInTransaction(() => {
161			store.upsertSession(buffer.session!);
162	
163			for (const turn of buffer.turns) {
164				store.insertTurn(turn);
165			}
166			for (const file of buffer.files) {
167				store.insertFile(file);
168			}
169			for (const ref of buffer.refs) {
170				store.insertRef(ref);
171			}
172		});
173	
174		// Help GC by clearing references — buffer is a local variable so this
175		// is defensive; it becomes unreachable when the function returns.
176		buffer.turns.length = 0;
177		buffer.files.length = 0;
178		buffer.refs.length = 0;
179	}
