189	 * This is the streaming callback — called once per line, no accumulation.
190	 */
191	function processEntry(
192		entry: IDebugLogEntry,
193		sessionId: string,
194		buffer: PerSessionWriteBuffer,
195		state: TurnPairingState,
196	): void {
197		switch (entry.type) {
198			case 'session_start':
199				processSessionStart(entry, sessionId, buffer);
200				break;
201			case 'user_message':
202			case 'turn_start':
203				processUserMessage(entry, state);
204				break;
205			case 'agent_response':
206				processAssistantResponse(entry, sessionId, buffer, state);
207				break;
208			case 'tool_call':
209				processToolCall(entry, sessionId, buffer, state);
210				break;
211		}
212	}
